from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump_to = dict(jumps)
    destination = list(range(n + 1))

    for start in jump_to:
        cell = start
        while cell in jump_to:
            cell = jump_to[cell]
        destination[start] = cell

    states = [0]
    index = {0: 0}
    transitions = []
    reverse = [[] for _ in range(n + 1)]

    cursor = 0
    while cursor < len(states):
        cell = states[cursor]
        counts = {}

        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            landing = destination[landing]
            counts[landing] = counts.get(landing, 0) + 1

        transitions.append(counts)
        for landing in counts:
            reverse[landing].append(cell)
            if landing != n and landing not in index:
                index[landing] = len(states)
                states.append(landing)

        cursor += 1

    # Every reachable state must have a path to the terminal cell.
    can_finish = {n}
    stack = [n]
    while stack:
        cell = stack.pop()
        for predecessor in reverse[cell]:
            if predecessor not in can_finish:
                can_finish.add(predecessor)
                stack.append(predecessor)

    if any(cell not in can_finish for cell in states):
        return None

    # The expectation equations are (mI - C)E = m.
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for i, counts in enumerate(transitions):
        matrix[i][i] = m
        matrix[i][-1] = m
        for landing, count in counts.items():
            if landing != n:
                matrix[i][index[landing]] -= count

    # Bareiss elimination keeps all intermediate entries integral.
    previous_pivot = 1
    for k in range(size - 1):
        if matrix[k][k] == 0:
            pivot_row = next(
                i for i in range(k + 1, size) if matrix[i][k] != 0
            )
            matrix[k], matrix[pivot_row] = matrix[pivot_row], matrix[k]

        pivot_row = matrix[k]
        pivot = pivot_row[k]

        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0

        previous_pivot = pivot

    expectation = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][-1])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectation[j]
        expectation[i] = value / matrix[i][i]

    answer = expectation[0]
    return [answer.numerator, answer.denominator]
